func gaussianElim(A, b) = {
  local n = b.listLen()
  local Aug = []
  for (i: 1 .. n) {
    local row = copyList(A[i])
    row.add(b[i])
    Aug.add(row)
  }
  for (col: 1 .. n) {
    local maxRow = col
    local maxVal = abs(Aug[col][col])
    for (row: col+1 .. n) {
      if (abs(Aug[row][col]) > maxVal) {
        maxVal = abs(Aug[row][col])
        maxRow = row
      }
    }
    local tmp = Aug[col]
    Aug[col] = Aug[maxRow]
    Aug[maxRow] = tmp
    for (row: col+1 .. n) {
      local factor = Aug[row][col] / Aug[col][col]
      for (j: col .. n+1) {
        Aug[row][j] = Aug[row][j] - factor * Aug[col][j]
      }
    }
  }
  local x_sol = []
  for (i: 1 .. n) {
    x_sol.add(0)
  }
  for (i: n .. 1 step -1) {
    local s = Aug[i][n+1]
    for (j: i+1 .. n) {
      s = s - Aug[i][j] * x_sol[j]
    }
    x_sol[i] = s / Aug[i][i]
  }
  x_sol
}

