    for (i: 1 .. iters) {
      local grad = 2 * x
      x = x - lr * grad
    }
  } else if (method === "adam") {
    local lr = 0.01
    local beta1 = 0.9
    local beta2 = 0.999
    local eps = 1e-8
    local m_adam = 0
    local v_adam = 0
    for (i: 1 .. iters) {
      local g = 2 * x
      m_adam = beta1 * m_adam + (1 - beta1) * g
      v_adam = beta2 * v_adam + (1 - beta2) * g * g
      local m_hat = m_adam / (1 - beta1 ^ i)
      local v_hat = v_adam / (1 - beta2 ^ i)
      x = x - lr * m_hat / (sqrt(v_hat) + eps)
    }
  } else {
    local step = 1.0
    for (i: 1 .. iters) {
      local fx = x^2
      local x_try = x + (randFloat() - 0.5) * step
      if (x_try^2 < fx) {
        x = x_try
      }
      step = step * 0.995
    }
  }
  {"x_opt": x, "f_opt": x^2}
}

