func densityOfStates(energies, sigma, n_grid) = {
  local e_min = energies.min { m, n -> m < n }
  local e_max = energies.max { m, n -> m > n }
  local de = (e_max - e_min) / n_grid
  local E_grid = arange(e_min - sigma, e_max + sigma, de)
  local DOS = E_grid.map { e ->
    energies.reduce(0) { ei, s ->
      s + exp(-(e - ei)^2 / (2 * sigma^2)) / (sigma * sqrt(2 * 3.14159265))
    }
  }
  {"E": E_grid, "DOS": DOS}
}

