func standardize(signal) = {
  local n = signal.listLen()
  local mean = signal.reduce(0) { x, s -> x + s } / n
  local variance = signal.map { x -> (x - mean)^2 }.reduce(0) { x, s -> x + s } / n
  local std = sqrt(variance)
  signal.map { x -> (x - mean) / std }
}

